<script setup lang="ts">
import {computed,onMounted,reactive,ref} from "vue";import GradingPanel from "./GradingPanel.vue";import EarlyChildhoodPanel from "./EarlyChildhoodPanel.vue";import {Pige360SessionClient,type ApiProblem} from "@pige360/auth";import {TransactionalOutbox,createOfflineStore,type SyncOperation} from "@pige360/offline-sync";
type Row=Record<string,any>;type AttendanceEntry={status_code:string;minutes_present:number|null;observation:string};const api=new Pige360SessionClient();const ready=ref(false),auth=ref(false),busy=ref(false),error=ref(""),notice=ref(""),online=ref(navigator.onLine);const email=ref(""),password=ref("");const ctx=ref<Row>({branding:{},assignments:[],sessions:[]});const roster=ref<Row|null>(null);const attendance=reactive<Record<string,AttendanceEntry>>({});const webOutbox=new TransactionalOutbox<any>();let nativeStore:ReturnType<typeof createOfflineStore>=null;const plan=reactive({assignment_id:"",title:"",start_date:"",end_date:"",content:""});const b=computed(()=>ctx.value.branding||{}),school=computed(()=>b.value.short_name||b.value.trade_name||b.value.legal_name||"Instituição");function m(e:unknown){const p=(e as Error&{problem?:ApiProblem}).problem;return p?.detail||(e instanceof Error?e.message:"Erro");}function theme(){document.documentElement.style.setProperty("--brand-primary",b.value.primary_color||"#006D77");document.documentElement.style.setProperty("--brand-secondary",b.value.secondary_color||"#0D1B2A");document.title=`${school.value} — Professor`;}async function load(){ctx.value=await api.request<Row>("/portal/teacher/me");theme();const c=api.claims();if(c?.tid&&c.sub){nativeStore=createOfflineStore(c.tid,c.sub);if(nativeStore)await nativeStore.initialize();}if(online.value)await sync();}async function boot(){window.addEventListener("online",()=>{online.value=true;void sync();});window.addEventListener("offline",()=>online.value=false);try{await api.initialize();auth.value=!!api.tokens;if(auth.value)await load();}catch(e){error.value=m(e);}finally{ready.value=true;}}async function login(){busy.value=true;try{await api.login(email.value,password.value);auth.value=true;await load();}catch(e){error.value=m(e);}finally{busy.value=false;}}async function logout(){await api.logout();auth.value=false;ctx.value={};roster.value=null;}async function openSession(s:Row){busy.value=true;try{roster.value=await api.request<Row>(`/portal/teacher/sessions/${s.id}/roster`);for(const st of roster.value.items||[]){attendance[st.student_id]={status_code:st.attendance?.status_code||"present",minutes_present:st.attendance?.minutes_present??null,observation:st.attendance?.observation||""};}}catch(e){error.value=m(e);}finally{busy.value=false;}}
function attendanceFor(studentId:string):AttendanceEntry{return attendance[studentId]??(attendance[studentId]={status_code:"present",minutes_present:null,observation:""});}
function operationForRoster():SyncOperation<any>{if(!roster.value)throw new Error("Sessão não selecionada");const records=(roster.value.items||[]).map((s:Row)=>({student_id:s.student_id,...attendance[s.student_id]}));return{idempotencyKey:`attendance-${roster.value.session_id}-${crypto.randomUUID()}`,aggregateType:"attendance_call",aggregateId:roster.value.session_id,baseRevision:Number(roster.value.call?.current_version||0),localRevision:Number(roster.value.call?.current_version||0)+1,payload:{records,mode:"all_present_exceptions",origin:online.value?"online":"offline",device_id:"teacher-app"},createdAt:new Date().toISOString()};}
async function saveCall(){try{const op=operationForRoster();if(!online.value){if(nativeStore)await nativeStore.enqueue(op);else webOutbox.enqueue(op);notice.value="Chamada salva na outbox offline.";return;}await sendOp(op);notice.value="Rascunho da chamada salvo.";await openSession(ctx.value.sessions.find((x:Row)=>x.id===roster.value?.session_id));}catch(e){error.value=m(e);}}
async function sendOp(op:SyncOperation<any>){const result=await api.request<Row>(`/class-sessions/${op.aggregateId}/attendance`,{method:"PUT",headers:{"Content-Type":"application/json","Idempotency-Key":op.idempotencyKey},body:JSON.stringify(op.payload)});if(nativeStore)await nativeStore.applyResult(op.idempotencyKey,result);return result;}
async function sync(){if(!online.value||!auth.value)return;try{if(nativeStore){for(const op of await nativeStore.pending<any>(100)){await sendOp({idempotencyKey:op.idempotency_key,aggregateType:op.aggregate_type,aggregateId:op.aggregate_id,baseRevision:op.base_revision,localRevision:op.base_revision+1,payload:op.payload,createdAt:op.created_at});}}else{for(const op of webOutbox.pending(100)){await sendOp(op);webOutbox.acknowledge(op.idempotencyKey);}}}catch(e){error.value=`Sincronização pendente: ${m(e)}`;}}
async function submitCall(){if(!roster.value)return;try{if(!online.value){error.value="Conecte-se à internet para enviar e fechar a chamada.";return;}const fresh=await api.request<Row>(`/portal/teacher/sessions/${roster.value.session_id}/roster`);if(!fresh.call){error.value="Salve o rascunho antes de enviar.";return;}await api.request(`/class-sessions/${roster.value.session_id}/attendance/submit`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({expected_call_version:fresh.call.current_version,origin:"online",device_id:"teacher-app"})});notice.value="Chamada enviada.";await load();await openSession(ctx.value.sessions.find((x:Row)=>x.id===roster.value?.session_id)||{id:roster.value.session_id});}catch(e){error.value=m(e);}}
async function createPlan(){const a=ctx.value.assignments.find((x:Row)=>x.id===plan.assignment_id);if(!a){error.value="Selecione uma atribuição.";return;}const period=(ctx.value.academic_periods||[]).filter((x:Row)=>x.academic_year_id===a.academic_year_id&&x.starts_on<=plan.start_date&&x.ends_on>=plan.end_date).sort((x:Row,y:Row)=>(x.period_type==="annual"?1:0)-(y.period_type==="annual"?1:0))[0];if(!period){error.value="Não existe período acadêmico ativo contendo as datas do planejamento.";return;}try{await api.request("/teaching-plans",{method:"POST",headers:{"Content-Type":"application/json","Idempotency-Key":`plan-${crypto.randomUUID()}`},body:JSON.stringify({institution_id:a.institution_id,unit_id:a.unit_id,academic_period_id:period.id,program_id:a.program_id,curriculum_id:a.curriculum_id,class_group_id:a.class_group_id,component_id:a.component_id,teacher_ids:[api.claims()?.sub],plan_type:"weekly",title:plan.title,start_date:plan.start_date,end_date:plan.end_date,objectives:[],skills:[],competencies:[],curriculum_links:[],content:plan.content.split("\n").filter(Boolean),methodologies:[],resources:[],accommodations:[],assessments:[],homework:[],references:[],attachments:[],approval_required:true})});notice.value="Planejamento salvo.";}catch(e){error.value=m(e);}}
function dt(v:any){return v?new Intl.DateTimeFormat("pt-BR",{dateStyle:"short",timeStyle:"short"}).format(new Date(v)):"—";}onMounted(boot);
</script>
<template><div v-if="!ready" class="center">Inicializando diário…</div><div v-else-if="!auth" class="login"><form @submit.prevent="login"><div class="mark">✎</div><span>Portal do Professor</span><h1>Diário e planejamento</h1><label>E-mail<input v-model="email" type="email" required></label><label>Senha<input v-model="password" type="password" required></label><p v-if="error" class="error">{{error}}</p><button>Entrar</button></form></div><div v-else class="shell"><header><div><strong>{{school}}</strong><small>{{ctx.person?.full_name}} · {{online?'online':'offline'}}</small></div><div><button class="sync" @click="sync">Sincronizar</button><button @click="logout">Sair</button></div></header><main><div v-if="error" class="flash error">{{error}}</div><div v-if="notice" class="flash success">{{notice}}</div><section class="hero"><span>Professor</span><h1>{{ctx.person?.social_name||ctx.person?.full_name}}</h1><p>{{ctx.assignments?.length||0}} atribuições ativas · {{ctx.sessions?.length||0}} sessões recentes</p></section><section class="grid"><div class="panel"><h2>Próximas e últimas aulas</h2><button class="session" v-for="s in ctx.sessions" :key="s.id" @click="openSession(s)"><div><strong>{{dt(s.scheduled_start)}}</strong><small>{{s.payload?.title||s.modality}} · {{s.status}}</small></div><span>›</span></button><p v-if="!ctx.sessions?.length" class="empty">Nenhuma sessão atribuída.</p></div><form class="panel form" @submit.prevent="createPlan"><h2>Novo planejamento semanal</h2><label>Atribuição<select v-model="plan.assignment_id" required><option value="">Selecione</option><option v-for="a in ctx.assignments" :key="a.id" :value="a.id">{{a.class_group_name}} — {{a.component_name}}</option></select></label><label>Título<input v-model="plan.title" required></label><div class="cols"><label>Início<input v-model="plan.start_date" type="date" required></label><label>Fim<input v-model="plan.end_date" type="date" required></label></div><label>Conteúdo<textarea v-model="plan.content" rows="4"></textarea></label><button>Salvar rascunho</button></form></section><section v-if="roster" class="panel attendance"><div class="section-title"><div><h2>Chamada em sala</h2><small>{{roster.session_status}} · versão {{roster.call?.current_version||0}}</small></div><span class="pill" :class="online?'ok':'warn'">{{online?'Online':'Offline'}}</span></div><div class="student" v-for="s in roster.items" :key="s.student_id"><div><strong>{{s.social_name||s.full_name}}</strong><small>{{s.registration_number}}</small></div><select v-model="attendanceFor(s.student_id).status_code"><option value="present">Presente</option><option value="absent">Falta</option><option value="late">Atraso</option><option value="justified_absence">Falta justificada</option><option value="early_departure">Saída antecipada</option><option value="remote_present">Presente remoto</option></select><input v-model="attendanceFor(s.student_id).observation" placeholder="Observação"></div><div class="actions"><button class="secondary" @click="saveCall">Salvar rascunho</button><button @click="submitCall">Enviar chamada</button></div></section><EarlyChildhoodPanel :api="api" :assignments="ctx.assignments||[]" @notice="notice=$event" @error="error=$event" /><GradingPanel :api="api" :assignments="ctx.assignments||[]" :periods="ctx.academic_periods||[]" @notice="notice=$event" @error="error=$event" /></main></div></template>
